227	          @for (item of order.items; track item.productId + ':' + item.supplierId) {
228	            <li class="order-confirmation__item">
229	              {{ item.productName }} ({{ item.supplierName }}) — {{ item.quantity }} × {{ item.unitPrice | number: '1.2-2' }} € =
230	              {{ item.lineTotal | number: '1.2-2' }} €
231	            </li>
