127	+    ```ts
128	+    import { Component, effect, inject, input, signal } from '@angular/core';
129	+    import { DatePipe, DecimalPipe } from '@angular/common';
130	+    import type { Subscription } from 'rxjs';
131	+
132	+    import { Order, OrdersApi } from '../../core/api/orders.api';
133	+
134	+    const STATUS_LABELS: Record<string, string> = {
135	+      Received: 'Eingegangen',
136	+    };
137	+
138	+    @Component({
139	+      selector: 'app-order-confirmation',
140	+      imports: [DatePipe, DecimalPipe],
141	+      templateUrl: './order-confirmation.html',
142	+    })
143	+    export class OrderConfirmation {
144	+      private readonly ordersApi = inject(OrdersApi);
145	+      private subscription: Subscription | undefined;
146	+
147	+      readonly publicId = input.required<string>();
148	+
149	+      protected readonly order = signal<Order | null>(null);
150	+      protected readonly loading = signal(false);
151	+      protected readonly notFound = signal(false);
152	+      protected readonly error = signal(false);
153	+
154	+      constructor() {
155	+        effect((onCleanup) => {
156	+          const publicId = this.publicId();
157	+          this.loadOrder(publicId);
158	+          onCleanup(() => this.subscription?.unsubscribe());
159	+        });
160	+      }
161	+
162	+      protected statusLabel(status: string): string {
163	+        return STATUS_LABELS[status] ?? status;
164	+      }
165	+
166	+      private loadOrder(publicId: string): void {
167	+        this.order.set(null);
168	+        this.notFound.set(false);
169	+        this.error.set(false);
170	+        this.loading.set(true);
171	+        this.subscription?.unsubscribe();
172	+        this.subscription = this.ordersApi.getOrder(publicId).subscribe({
173	+          next: (order) => {
174	+            if (this.publicId() !== publicId) {
175	+              return;
176	+            }
177	+            this.order.set(order);
178	+            this.loading.set(false);
179	+          },
180	+          error: (err) => {
181	+            if (this.publicId() !== publicId) {
182	+              return;
183	+            }
184	+            this.loading.set(false);
185	+            if (err?.status === 404) {
186	+              this.notFound.set(true);
187	+            } else {
188	+              this.error.set(true);
189	+            }
190	+          },
191	+        });
192	+      }
193	+    }
194	+    ```
