439	+    {
440	+        var order = await db.Orders
441	+            .AsNoTracking()
442	+            .Include(o => o.Items).ThenInclude(i => i.Product)
443	+            .Include(o => o.Items).ThenInclude(i => i.Supplier)
444	+            .FirstOrDefaultAsync(o => o.PublicId == publicId, cancellationToken);
445	+
446	+        if (order is null)
447	+        {
448	+            return null;
449	+        }
450	+
451	+        var items = order.Items
452	+            .OrderBy(i => i.Id)
453	+            .Select(i => new OrderItemResponseDto
454	+            {
455	+                ProductId = i.ProductId,
456	+                ProductName = i.Product.Name,
457	+                SupplierId = i.SupplierId,
458	+                SupplierName = i.Supplier.Name,
459	+                UnitPrice = i.UnitPriceAtOrder,
460	+                Quantity = i.Quantity,
461	+                LineTotal = i.UnitPriceAtOrder * i.Quantity,
462	+            })
463	+            .ToList();
464	+
465	+        return new OrderDto
466	+        {
467	+            PublicId = order.PublicId,
468	+            Status = order.Status.ToString(),
469	+            Delivery = new DeliveryDto
470	+            {
471	+                Name = order.DeliveryName,
472	+                Street = order.DeliveryStreet,
473	+                PostalCode = order.DeliveryPostalCode,
474	+                City = order.DeliveryCity,
475	+                Country = order.DeliveryCountry,
476	+                Email = order.DeliveryEmail,
477	+                Phone = order.DeliveryPhone,
478	+            },
479	+            Items = items,
480	+            TotalAmount = items.Sum(i => i.LineTotal),
481	+            CreatedAt = order.CreatedAt,
482	+        };
483	+    }
484	 }
